// TestGPUCtxDump (temporary, KERNELS.md G4 debugging): the last block's
// fp16 context after an edit prefill, to a file named by QIMAGE_CTX_DUMP.
func TestGPUCtxDump(t *testing.T) {
	out := os.Getenv("QIMAGE_CTX_DUMP")
	if out == "" {
		t.Skip("set QIMAGE_CTX_DUMP")
	}
	m := loadRun(t, editRef)
	dev, done := newTestDevice(t)
	defer done()
	embeds := loadMat(t, m, "prompt_embeds")
	cond := loadMat(t, m, "cond_latents")
	mask := loadMat(t, m, "image_pad_mask")
	pad := make([]bool, mask.Rows*mask.Cols)
	for i := range pad {
		pad[i] = mask.Data[i] != 0
	}
	side := m.Size / 16
	condShape := [3]int{m.CondLatentShape[0], m.CondLatentShape[1], m.CondLatentShape[2]}
	lay, err := dit.LayoutFromPadMask(pad, [][3]int{condShape}, [3]int{1, side, side})
	if err != nil {
		t.Fatal(err)
	}
	for _, s := range lay.Segments {
		t.Logf("segment %d-%d text %v", s.Start, s.End, s.Text)
	}
	g, err := newGPU(t, dev, transformer, lay.Seq(), lay.PrefixLen, embeds.Rows)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()
	if err := g.BeginImage(embeds, lay, cond); err != nil {
		t.Fatal(err)
	}
	scfg, err := pipeline.LoadSchedConfig(scheduler)
	if err != nil {
		t.Fatal(err)
	}
	sched, err := scfg.Timesteps(m.Steps, side*side)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := g.Step(loadMat(t, m, "noise").Clone(), sched.T(0), true); err != nil {
		t.Fatal(err)
	}
	rows := lay.Seq()
	h := g.hbuf.ReadUint16At(int(g.hCtx), rows*g.ldaDim)
	f, err := os.Create(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	binary.Write(f, binary.LittleEndian, uint32(rows))
	binary.Write(f, binary.LittleEndian, uint32(g.ldaDim))
	binary.Write(f, binary.LittleEndian, uint32(g.dim))
	binary.Write(f, binary.LittleEndian, h)
}
EOF
